DELIMITER ;;
CREATE PROCEDURE `JumlahKelas`(
    IN p_nama_kelas VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
)
BEGIN
    SELECT
        c.id AS id_kelas,
        c.class_name AS nama_kelas,
        (
            SELECT COUNT(*)
            FROM classes AS c2
            WHERE c2.class_name LIKE CONCAT('%', p_nama_kelas, '%')
        ) AS jumlah_kelas_cocok
    FROM classes AS c
    WHERE c.class_name LIKE CONCAT('%', p_nama_kelas, '%')
    ORDER BY c.class_name;
END ;;
DELIMITER ;
