/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE PROCEDURE `JumlahSiswa`(OUT `p_nama_kelas` VARCHAR(100))
BEGIN
    SELECT
        u.id AS id_siswa,
        u.fullname AS nama_siswa,
        c.class_name AS nama_kelas,
        (
            SELECT COUNT(*)
            FROM users AS u2
            INNER JOIN classes AS c2
                ON c2.id = u2.class_id
            WHERE c2.class_name LIKE CONCAT('%', p_nama_kelas, '%')
        ) AS jumlah_siswa
    FROM users AS u
    INNER JOIN classes AS c
        ON c.id = u.class_id
    WHERE c.class_name LIKE CONCAT('%', p_nama_kelas, '%')
    ORDER BY u.fullname;
END ;;
DELIMITER ;
