CREATE PROCEDURE `LihatJadwal`(OUT `p_hari` VARCHAR(20))
BEGIN
    SELECT *
    FROM schedules
    WHERE day_of_week LIKE CONCAT('%', p_hari, '%')
    ORDER BY start_time ASC;
END ;;
DELIMITER ;
