DELIMITER ;;
CREATE PROCEDURE `LihatRiwayatSiklus`(
    IN p_putaran VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
)
BEGIN
    SELECT
        id,
        cycle_name,
        start_date,
        end_date,
        class_mapping_summary,
        changed_by,
        created_at,
        updated_at
    FROM cycle_histories
    WHERE cycle_name LIKE CONCAT('%', p_putaran, '%')
    ORDER BY start_date DESC;
END ;;
DELIMITER ;
